package main

import (
	"context"
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"unicode"

	"os/exec"

	tfgen "github.com/Lenstra/terraform-provider-logto/scripts/terraform-generator"
)

func main() {
	err := Main()
	if err != nil {
		log.Fatalf("err: %v", err)
	}
}

func Main() error {
	ctx := context.Background()
	spec, _, err := tfgen.Load(ctx)
	if err != nil {
		return err
	}

	// The checked-in specification is already merged and reviewed.

	content, err := json.MarshalIndent(spec, "", "\t")
	if err != nil {
		return err
	}
	err = os.WriteFile("provider_code_spec.json", content, 0o644)
	if err != nil {
		return err
	}

	input := "provider_code_spec.json"
	output := "internal/provider"
	if err := generate(input, output); err != nil {
		return err
	}
	if err := patchObjectStateConversions(output); err != nil {
		return err
	}
	if err := generateAdditionalFiles(output); err != nil {
		return err
	}
	return exec.Command("gofmt", "-w", output).Run()
}

func generate(input, output string) error {
	cmd := exec.Command(
		"go", "run", "github.com/hashicorp/terraform-plugin-codegen-framework/cmd/tfplugingen-framework@v0.4.1",
		"generate",
		"all",
		"--input="+input,
		"--output="+output,
	)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

func generateAdditionalFiles(output string) error {
	entries, err := os.ReadDir(output)
	if err != nil {
		return err
	}

	for _, entry := range entries {
		if entry.IsDir() && strings.HasPrefix(entry.Name(), "resource_") {
			// This resource owns its schema and implementation; it is not generated.
			if entry.Name() == "resource_application_secret" {
				continue
			}
			packageName := strings.TrimPrefix(entry.Name(), "resource_")
			resourceName := toCamelCase(packageName)
			path := fmt.Sprintf("internal/provider/%s/%s_resource_impl_gen.go", entry.Name(), packageName)
			content := []byte(template(packageName, resourceName))
			if err := os.WriteFile(path, content, 0o644); err != nil {
				return err
			}
		}
	}
	return nil
}

func template(packageName, resourceName string) string {
	noImportState := map[string]struct{}{
		"api_resource_scope": {},
	}

	skipImportState := false
	if _, found := noImportState[packageName]; found {
		skipImportState = true
	}

	importStateBlock := ""

	varBlock := "_ resource.Resource                = &" + resourceName + "Resource{}\n" +
		"\t_ resource.ResourceWithConfigure   = &" + resourceName + "Resource{}"

	imports := `"context"
	"github.com/Lenstra/terraform-provider-logto/client"
	"github.com/hashicorp/terraform-plugin-framework/resource"`

	if !skipImportState {
		importStateBlock = fmt.Sprintf(`func (r *%[1]sResource) ImportState(ctx context.Context, req resource.ImportStateRequest, resp *resource.ImportStateResponse) {
	resource.ImportStatePassthroughID(ctx, path.Root("id"), req, resp)
}`, resourceName)

		varBlock += "\n\t_ resource.ResourceWithImportState = &" + resourceName + "Resource{}"

		imports += `
	"github.com/hashicorp/terraform-plugin-framework/path"`
	}

	return fmt.Sprintf(`// Code generated by terraform-generator DO NOT EDIT.
package resource_%[3]s

import (
	%[4]s
)

// Ensure the implementation satisfies the expected interfaces.
var (
	%[5]s
)

type %[1]sResource struct {
	client *client.Client
}

func %[2]sResource() resource.Resource {
	return &%[1]sResource{}
}

func (r *%[1]sResource) Metadata(_ context.Context, req resource.MetadataRequest, resp *resource.MetadataResponse) {
	resp.TypeName = req.ProviderTypeName + "_%[3]s"
}

func (r *%[1]sResource) Schema(ctx context.Context, req resource.SchemaRequest, resp *resource.SchemaResponse) {
	resp.Schema = %[2]sResourceSchema(ctx)
}

func (r *%[1]sResource) Configure(_ context.Context, req resource.ConfigureRequest, _ *resource.ConfigureResponse) {
	if req.ProviderData == nil {
		return
	}
	client, ok := req.ProviderData.(*client.Client)
	if !ok {
		return
	}
	r.client = client
}

%[6]s
`, resourceName, toPascalCase(packageName), packageName, imports, varBlock, importStateBlock)
}

func toCamelCase(s string) string {
	parts := strings.FieldsFunc(s, func(r rune) bool {
		return r == '_' || r == '-' || unicode.IsSpace(r)
	})

	for i, p := range parts {
		if len(p) > 0 {
			if i == 0 {
				parts[i] = strings.ToLower(p)
			} else {
				parts[i] = strings.ToUpper(p[:1]) + strings.ToLower(p[1:])
			}
		}
	}
	return strings.Join(parts, "")
}

func toPascalCase(s string) string {
	parts := strings.FieldsFunc(s, func(r rune) bool {
		return r == '_' || r == '-' || unicode.IsSpace(r)
	})
	for i, p := range parts {
		if len(p) > 0 {
			parts[i] = strings.ToUpper(p[:1]) + strings.ToLower(p[1:])
		}
	}
	return strings.Join(parts, "")
}

// The pinned generator does not handle null/unknown objects in ValueFromObject.
// Add the missing conversions structurally, before formatting the generated code.
func patchObjectStateConversions(root string) error {
	return filepath.WalkDir(root, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.IsDir() || !strings.HasSuffix(path, "_gen.go") {
			return nil
		}
		content, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		fset := token.NewFileSet()
		file, err := parser.ParseFile(fset, path, content, 0)
		if err != nil {
			return err
		}
		type insertion struct {
			offset int
			text   string
		}
		edits := []insertion{}
		constructors := map[string]bool{}
		for _, declaration := range file.Decls {
			if fn, ok := declaration.(*ast.FuncDecl); ok {
				constructors[fn.Name.Name] = true
			}
		}
		for _, declaration := range file.Decls {
			fn, ok := declaration.(*ast.FuncDecl)
			if !ok || fn.Name.Name != "ValueFromObject" || fn.Recv == nil || fn.Body == nil {
				continue
			}
			receiver, ok := fn.Recv.List[0].Type.(*ast.Ident)
			if !ok || !strings.HasSuffix(receiver.Name, "Type") {
				continue
			}
			name := strings.TrimSuffix(receiver.Name, "Type")
			if !constructors["New"+name+"ValueNull"] || !constructors["New"+name+"ValueUnknown"] {
				return fmt.Errorf("missing generated object constructors in %s", path)
			}
			edits = append(edits, insertion{fset.Position(fn.Body.Lbrace).Offset + 1, "\n\tif in.IsNull() { return New" + name + "ValueNull(), nil }\n\tif in.IsUnknown() { return New" + name + "ValueUnknown(), nil }\n"})
		}
		sort.Slice(edits, func(i, j int) bool { return edits[i].offset > edits[j].offset })
		for _, edit := range edits {
			content = append(append(append([]byte{}, content[:edit.offset]...), []byte(edit.text)...), content[edit.offset:]...)
		}
		if len(edits) > 0 {
			return os.WriteFile(path, content, 0o644)
		}
		return nil
	})
}
